-- ONLY for an empty, disposable local PostgreSQL database. Not a hosted migration.
create role anon;
create role authenticated;
create schema auth;
create schema storage;
create table auth.users(id uuid primary key);
insert into auth.users values ('00000000-0000-0000-0000-000000000001');
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function auth.role() returns text language sql stable as $$ select current_user::text $$;
grant usage on schema auth, public, storage to anon, authenticated;
create table public."Client" (id bigint generated by default as identity primary key, first_name text not null, last_name text not null, phone text not null, instagram text, origin text, london_based boolean, email text, dob text);
create table public."Status" (id bigint generated by default as identity primary key, status text not null);
insert into public."Status"(id,status) values (1,'In Progress'),(2,'Completed'),(3,'In Review'),(4,'Upcoming'),(5,'Expired');
create table public."Project" (id bigint generated by default as identity primary key, client_id bigint not null references public."Client" on delete restrict, project_title text not null unique, status_id bigint not null references public."Status", cartridge_brand text, needle_config text, date_start date not null, target_end_date date, agreed_price float8, deposit_received boolean, client_feedback text, placement text, size text, style text, reference text, design_notes text, deposit_amount float8, artist_notes text);
create table public."Session" (id bigint generated by default as identity primary key, project_id bigint not null references public."Project" on delete restrict, status_id bigint not null references public."Status", appointment_date date not null, appointment_time time not null, duration time, amount_paid float8, session_notes text, img_urls text[]);
create table storage.buckets(id text primary key, public boolean, file_size_limit bigint, allowed_mime_types text[]);
insert into storage.buckets values ('Session Photos',true,null,null);
create table storage.objects(id bigint generated by default as identity, bucket_id text, name text);
alter table storage.objects enable row level security;
create policy old_upload on storage.objects for insert with check (bucket_id='Session Photos');
grant all on all tables in schema public, storage to anon, authenticated;
grant usage on all sequences in schema public, storage to anon, authenticated;
create policy old_access on public."Client" for all using(true) with check(true);
create policy old_access on public."Project" for all using(true);
create policy old_access on public."Session" for all using(true);
create policy old_access on public."Status" for select using(true);
